import joblib, numpy as np, itertools
animal='QLAK-CA1-08'
dat=joblib.load(f'/app/data/{animal}')[animal]
name_to_day={str(e[0]):i for i,e in enumerate(dat['envs'])}
examples=['rectangle','u','l','glenn','bit donut','o','t','+','i']
# observed occupied bin coords from min-shift + common scale
obs={}
for env in examples:
    day=name_to_day[env]
    pos=dat['position'][day].T.astype(float)
    pos=pos-pos.min(axis=0, keepdims=True)
    bin_down=(np.nanmax(pos)+1e-9)/3.0
    bins=np.floor(pos/bin_down).astype(int)
    bins=np.clip(bins,0,2)
    occ={(int(x),int(y)) for x,y in bins}
    blocked=dat['blocked'][day][0]
    blocked=np.array(blocked, dtype=float).reshape(-1)
    blocked=[] if (blocked.size==1 and blocked[0]==-1) else [int(v) for v in blocked]
    obs[env]=(occ,set(blocked))

def map_id(x,y,swap=False,flipx=False,flipy=False,row_major='xy'):
    a,b=(y,x) if swap else (x,y)
    if flipx:
        a=2-a
    if flipy:
        b=2-b
    if row_major=='xy':
        return a*3+b
    else:
        return b*3+a

for swap,flipx,flipy,row_major in itertools.product([False,True],[False,True],[False,True],['xy','yx']):
    ok=True
    mismatches=[]
    for env,(occ,blocked) in obs.items():
        occupied_ids={map_id(x,y,swap,flipx,flipy,row_major) for x,y in occ}
        missing=set(range(9))-occupied_ids
        if missing!=blocked:
            ok=False
            mismatches.append((env, sorted(blocked), sorted(missing)))
    if ok:
        print('MATCH', swap, flipx, flipy, row_major)
        break
else:
    print('No exact match')
    # score by symmetric difference total
    scores=[]
    for swap,flipx,flipy,row_major in itertools.product([False,True],[False,True],[False,True],['xy','yx']):
        score=0
        for env,(occ,blocked) in obs.items():
            occupied_ids={map_id(x,y,swap,flipx,flipy,row_major) for x,y in occ}
            missing=set(range(9))-occupied_ids
            score+=len(missing.symmetric_difference(blocked))
        scores.append((score,swap,flipx,flipy,row_major))
    for item in sorted(scores)[:10]:
        print('score', item)
